// Terminal line discipline.
//
// This is the Zig counterpart of the input/output halves of NetBSD's
// sys/kern/tty.c, reduced to a single terminal over the console: canonical
// input with line editing and echo, output with newline translation, and the
// ioctls that get and set the attributes. Signals generated by the control
// characters (VINTR, VSUSP, ...) are noted here but delivered by the signal
// layer once it exists.

const termios: type = @import("../sys/termios.zig");
const ttycom: type = @import("../sys/ttycom.zig");
const consio: type = @import("../sys/consio.zig");
const signal: type = @import("../sys/signal.zig");
const errno: type = @import("../sys/errno.zig");
const cons: type = @import("../dev/cons.zig");
const file: type = @import("../sys/file.zig");
const kern_proc: type = @import("kern_proc.zig");
const kern_signal: type = @import("kern_signal.zig");

/// Longest canonical line.
pub const LINE_MAX: usize = 256;

/// A terminal.
pub const Tty: type = struct {
    /// Terminal attributes.
    termios: termios.Termios,
    /// Window size.
    winsize: termios.Winsize,
    /// The line being edited in canonical mode.
    line: [LINE_MAX]u8,
    line_len: usize,
    /// A completed line waiting to be read.
    ready: [LINE_MAX]u8,
    ready_len: usize,
    ready_pos: usize,
    have_line: bool,
    /// A control character asked the reader to interrupt its read.
    interrupt: bool,
    /// The session this is the controlling terminal of (0: none) and its
    /// foreground process group, which receives the signals ^C, ^\ and ^Z
    /// generate and alone may read.
    sid: i32,
    pgrp: i32,
    /// A process is inside the line discipline (it may be preempted there),
    /// so rint() must not run it concurrently.
    busy: bool,
};

/// The terminals initialised so far (the console is the only one).
var ttys: [1]?*Tty = .{null};

/// Prepare a terminal with the default attributes.
pub fn init(t: *Tty) void {
    t.termios = termios.defaults();
    t.winsize = .{ .ws_row = 24, .ws_col = 80, .ws_xpixel = 0, .ws_ypixel = 0 };
    t.line_len = 0;
    t.ready_len = 0;
    t.ready_pos = 0;
    t.have_line = false;
    t.interrupt = false;
    t.sid = 0;
    t.pgrp = 0;
    t.busy = false;
    ttys[0] = t;
}

/// Run typed characters through the line discipline even when nobody reads
/// the terminal, so ^C and ^Z reach a foreground job that is busy or asleep
/// (FreeBSD does this from the keyboard interrupt, ttydisc_rint). Called by
/// the scheduler between processes.
pub fn rint() void {
    for (ttys) |maybe| {
        const t = maybe orelse continue;
        // Only for a controlling terminal: before a session owns it there
        // is no foreground group to signal.
        if (t.busy or t.pgrp == 0 or !cons.cnInputReady()) continue;
        t.busy = true;
        while (cons.cngetcPoll()) |c| {
            input(t, c);
        }
        t.busy = false;
    }
}

/// A session leader exited: the terminal it controlled is released and its
/// foreground group gets SIGHUP (and SIGCONT, should it be stopped).
pub fn sessionExit(sid: i32) void {
    for (ttys) |maybe| {
        const t = maybe orelse continue;
        if (t.sid != sid) continue;
        if (t.pgrp != 0) {
            _ = kern_signal.gsignal(t.pgrp, signal.SIGHUP);
            _ = kern_signal.gsignal(t.pgrp, signal.SIGCONT);
        }
        t.sid = 0;
        t.pgrp = 0;
    }
}

/// Post the signal a control character generates: to the foreground group,
/// or, on a terminal no session controls, to the process using it. Returns
/// whether anyone received it.
fn ttySignal(t: *Tty, sig: u32) bool {
    if (t.pgrp != 0) {
        return kern_signal.gsignal(t.pgrp, sig) > 0;
    }
    const p: *@import("../sys/proc.zig").Proc = kern_proc.current;
    if (kern_signal.handler(p, sig) == signal.SIG_IGN) return false;
    kern_signal.psignal(p, sig);
    return true;
}

/// Echo one byte to the terminal.
fn echo(t: *Tty, c: u8) void {
    _ = t;
    cons.cnputc(c);
}

/// Give the caller a byte typed on the terminal (the line discipline).
pub fn input(t: *Tty, c: u8) void {
    const lflag: u32 = t.termios.c_lflag;

    if ((lflag & termios.ISIG) != 0) {
        // ^C, ^\ and ^Z: discard the line and signal the foreground group.
        const sig: u32 = if (c == t.termios.c_cc[termios.VINTR])
            signal.SIGINT
        else if (c == t.termios.c_cc[termios.VQUIT])
            signal.SIGQUIT
        else if (c == t.termios.c_cc[termios.VSUSP])
            signal.SIGTSTP
        else
            0;
        if (sig != 0) {
            t.line_len = 0;
            if ((lflag & termios.ECHO) != 0) {
                echo(t, '^');
                echo(t, c + '@');
                echo(t, '\n');
            }
            if (ttySignal(t, sig) and sig != signal.SIGTSTP) {
                t.interrupt = true;
            }
            return;
        }
    }

    if ((lflag & termios.ICANON) == 0) {
        // Raw mode: hand the byte straight through.
        if (t.ready_len < t.ready.len) {
            t.ready[t.ready_len] = c;
            t.ready_len += 1;
            t.have_line = true;
        }
        return;
    }

    if (c == '\r' or c == '\n' or c == t.termios.c_cc[termios.VEOL]) {
        if ((lflag & termios.ECHO) != 0) {
            // The console layer turns the newline into CR-NL.
            echo(t, '\n');
        }
        if (t.line_len < t.line.len) {
            t.line[t.line_len] = '\n';
            t.line_len += 1;
        }
        // Publish the completed line.
        var i: usize = 0;
        while (i < t.line_len) : (i += 1) {
            t.ready[i] = t.line[i];
        }
        t.ready_len = t.line_len;
        t.ready_pos = 0;
        t.have_line = true;
        t.line_len = 0;
        return;
    }

    if (c == 0x7f or c == t.termios.c_cc[termios.VERASE]) {
        if (t.line_len > 0) {
            t.line_len -= 1;
            if ((lflag & termios.ECHO) != 0) {
                echo(t, '\x08');
                echo(t, ' ');
                echo(t, '\x08');
            }
        }
        return;
    }

    if ((lflag & termios.ECHO) != 0) {
        echo(t, c);
    }
    if (t.line_len < t.line.len) {
        t.line[t.line_len] = c;
        t.line_len += 1;
    }
}

/// Readiness for poll(2): whether a read would return data now (a whole line
/// in canonical mode, any character in raw mode), after running pending
/// input through the line discipline. Output never blocks.
pub fn poll(t: *Tty) u16 {
    t.busy = true;
    while (cons.cngetcPoll()) |c| {
        input(t, c);
    }
    t.busy = false;
    var ev: u16 = file.POLLOUT;
    if (t.have_line or t.interrupt) ev |= file.POLLIN;
    return ev;
}

/// Read up to `buf.len` bytes from the terminal, draining the device first.
/// Returns -EAGAIN when no completed line is ready.
pub fn read(t: *Tty, buf: []u8) isize {
    // Only the foreground group reads its controlling terminal. A
    // background reader is stopped with SIGTTIN; it waits (see sysRead) and
    // tries again once continued. If it would not stop, it gets EIO.
    const p: *@import("../sys/proc.zig").Proc = kern_proc.current;
    if (t.sid != 0 and p.sid == t.sid and t.pgrp != 0 and p.pgid != t.pgrp) {
        if (kern_signal.ignoredOrBlocked(p, signal.SIGTTIN)) {
            return -errno.EIO;
        }
        _ = kern_signal.gsignal(p.pgid, signal.SIGTTIN);
        return -errno.EAGAIN;
    }
    // Pull whatever the hardware has and run it through the line discipline.
    t.busy = true;
    while (cons.cngetcPoll()) |c| {
        input(t, c);
    }
    t.busy = false;
    if (t.interrupt) {
        t.interrupt = false;
        return -errno.EINTR;
    }
    if (!t.have_line) {
        return -errno.EAGAIN;
    }

    var n: usize = 0;
    while (n < buf.len and t.ready_pos < t.ready_len) : (n += 1) {
        buf[n] = t.ready[t.ready_pos];
        t.ready_pos += 1;
    }
    if (t.ready_pos >= t.ready_len) {
        t.have_line = false;
        t.ready_len = 0;
        t.ready_pos = 0;
    }
    return @intCast(n);
}

/// Write `buf` to the terminal. The console layer already maps a newline to
/// CR-NL (the serial driver and the graphical console each do it), so the line
/// discipline passes the bytes through rather than adding another CR when
/// OPOST|ONLCR is set.
pub fn write(t: *Tty, buf: []const u8) isize {
    _ = t;
    for (buf) |c| {
        cons.cnputc(c);
    }
    return @intCast(buf.len);
}

/// Handle a terminal ioctl. `arg` is a user pointer, dereferenced directly
/// because the caller's address space is current.
pub fn ioctl(t: *Tty, cmd: u64, arg: u64) i32 {
    switch (cmd) {
        ttycom.TIOCGETA => {
            const dst: [*]u8 = @ptrFromInt(arg);
            copyOut(dst, @ptrCast(&t.termios), @sizeOf(termios.Termios));
            return 0;
        },
        ttycom.TIOCSETA, ttycom.TIOCSETAW, ttycom.TIOCSETAF => {
            const src: [*]const u8 = @ptrFromInt(arg);
            copyIn(@ptrCast(&t.termios), src, @sizeOf(termios.Termios));
            return 0;
        },
        ttycom.TIOCGWINSZ => {
            // Prefer the real console size (framebuffer grid) when there is one.
            if (cons.cnSize()) |s| {
                t.winsize.ws_row = @intCast(s.rows);
                t.winsize.ws_col = @intCast(s.cols);
            }
            const dst: [*]u8 = @ptrFromInt(arg);
            copyOut(dst, @ptrCast(&t.winsize), @sizeOf(termios.Winsize));
            return 0;
        },
        ttycom.TIOCSWINSZ => {
            const src: [*]const u8 = @ptrFromInt(arg);
            copyIn(@ptrCast(&t.winsize), src, @sizeOf(termios.Winsize));
            return 0;
        },
        ttycom.TIOCSCTTY => {
            // A session leader without a terminal takes this one, unless
            // another live session holds it (root may steal it with arg 1).
            const p = kern_proc.current;
            if (p.sid != p.pid) return -@as(i32, errno.EPERM);
            if (t.sid == p.sid) return 0;
            if (t.sid != 0 and kern_proc.pfind(t.sid) != null and !(arg == 1 and p.euid == 0)) {
                return -@as(i32, errno.EPERM);
            }
            t.sid = p.sid;
            t.pgrp = p.pgid;
            return 0;
        },
        ttycom.TIOCNOTTY => {
            const p = kern_proc.current;
            if (t.sid != p.sid) return -@as(i32, errno.ENOTTY);
            if (p.sid == p.pid) sessionExit(p.sid);
            return 0;
        },
        ttycom.TIOCGSID => {
            if (t.sid == 0 or t.sid != kern_proc.current.sid) return -@as(i32, errno.ENOTTY);
            const dst: *align(1) i32 = @ptrFromInt(arg);
            dst.* = t.sid;
            return 0;
        },
        ttycom.TIOCGPGRP => {
            // Only for the caller's own controlling terminal.
            if (t.sid == 0 or t.sid != kern_proc.current.sid) return -@as(i32, errno.ENOTTY);
            const dst: *align(1) i32 = @ptrFromInt(arg);
            dst.* = t.pgrp;
            return 0;
        },
        ttycom.TIOCSPGRP => {
            // The new foreground group must belong to the terminal's session.
            const p = kern_proc.current;
            if (t.sid == 0 or t.sid != p.sid) return -@as(i32, errno.ENOTTY);
            const src: *align(1) const i32 = @ptrFromInt(arg);
            const pgid: i32 = src.*;
            if (pgid <= 0) return -@as(i32, errno.EINVAL);
            var ok: bool = false;
            for (&kern_proc.table) |*q| {
                if (q.state != .unused and q.state != .zombie and q.pgid == pgid and q.sid == p.sid) {
                    ok = true;
                    break;
                }
            }
            if (!ok) return -@as(i32, errno.EPERM);
            t.pgrp = pgid;
            return 0;
        },
        consio.KDGETMODE => {
            const dst: *align(1) i32 = @ptrFromInt(arg);
            dst.* = if (cons.cnGraphics()) consio.KD_GRAPHICS else consio.KD_TEXT;
            return 0;
        },
        consio.KDSETMODE => {
            // _IOWINT: the mode is the argument itself, not a pointer.
            const mode: i64 = @bitCast(arg);
            switch (mode) {
                consio.KD_TEXT => cons.cnSetGraphics(false, 0),
                consio.KD_GRAPHICS => cons.cnSetGraphics(true, kern_proc.current.pid),
                else => return -@as(i32, errno.EINVAL),
            }
            return 0;
        },
        ttycom.FIODGNAME => {
            // The console terminal is FreeBSD's first virtual terminal, so
            // ttyname(3) says /dev/ttyv0 (the name /etc/ttys knows).
            const a: *align(1) const ttycom.FiodgnameArg = @ptrFromInt(arg);
            const name: []const u8 = "ttyv0";
            const dst: [*]u8 = a.buf orelse return -@as(i32, errno.EFAULT);
            if (a.len <= name.len) return -@as(i32, errno.EINVAL);
            @memcpy(dst[0..name.len], name);
            dst[name.len] = 0;
            return 0;
        },
        ttycom.FIONREAD => {
            const dst: *align(1) i32 = @ptrFromInt(arg);
            dst.* = if (t.have_line) @intCast(t.ready_len - t.ready_pos) else 0;
            return 0;
        },
        else => return -@as(i32, @import("../sys/errno.zig").ENOTTY),
    }
}

fn copyOut(dst: [*]u8, src: [*]const u8, len: usize) void {
    var i: usize = 0;
    while (i < len) : (i += 1) {
        dst[i] = src[i];
    }
}

fn copyIn(dst: [*]u8, src: [*]const u8, len: usize) void {
    var i: usize = 0;
    while (i < len) : (i += 1) {
        dst[i] = src[i];
    }
}
